/* MapLibre + OpenFreeMap. All TTSpot listings here are explicitly fictional prelaunch examples. */
(()=>{
const regions={kl:{name:'KL / Selangor',center:[101.65,3.12],zoom:10.4},johor:{name:'Johor',center:[103.75,1.50],zoom:11.1},penang:{name:'Penang',center:[100.31,5.40],zoom:11.1}};
const spots=[
 ['kl','meets',101.636,3.11,'PJ night TT','Sample meet · Petaling Jaya area'],['kl','meets',101.705,3.155,'KL weekend crew','Sample meet · Kuala Lumpur area'],['kl','checkpoints',101.688,3.147,'City photo stop','Sample checkpoint · Kuala Lumpur area'],['kl','checkpoints',101.585,3.073,'Subang lepak stop','Sample checkpoint · Subang Jaya area'],['kl','vendors',101.616,3.102,'Detailing pit stop','Sample vendor · Petaling Jaya area'],['kl','vendors',101.535,3.08,'Workshop discovery','Sample vendor · Shah Alam area'],
 ['johor','meets',103.758,1.49,'JB weekend TT','Sample meet · Johor Bahru area'],['johor','checkpoints',103.724,1.471,'Southern photo stop','Sample checkpoint · Johor Bahru area'],['johor','vendors',103.777,1.529,'Johor car-care stop','Sample vendor · Johor Bahru area'],
 ['penang','meets',100.317,5.418,'Penang kaki kereta','Sample meet · George Town area'],['penang','checkpoints',100.332,5.403,'Island photo stop','Sample checkpoint · George Town area'],['penang','vendors',100.299,5.365,'Island car-care stop','Sample vendor · Penang area']
];
let map,region='kl',category='all',markers=[],loaded=false,timeout;
const world=document.createElement('div');world.className='tt-map-world';world.innerHTML='<div class="tt-map-canvas" aria-label="Interactive TTSpot map"></div><div class="tt-map-badge">TTSPOT · DEMO SPOTS</div><button class="tt-map-expand" type="button">Explore map ↗</button><div class="tt-map-status" role="status">Loading map…</div>';
const dashboard=document.querySelector('#dashboard-map-slot'),full=document.querySelector('#full-map-slot'),status=world.querySelector('.tt-map-status');dashboard.append(world);
function notice(text,retry=false){status.hidden=false;status.textContent=text;if(retry){const b=document.createElement('button');b.textContent='Retry';b.onclick=()=>{if(map){status.textContent='Loading map…';map.setStyle('https://tiles.openfreemap.org/styles/dark');watchLoad()}else init()};status.append(b)}}
function watchLoad(){clearTimeout(timeout);timeout=setTimeout(()=>{if(!loaded)notice('Map connection is taking longer than expected.',true)},18000)}
function fly(){if(!map)return;const r=regions[region];map.flyTo({center:r.center,zoom:r.zoom,duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:1000});}
function paint(){markers.forEach(m=>m.remove());markers=[];document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===category)));world.querySelector('.tt-map-badge').textContent=regions[region].name.toUpperCase()+' · DEMO SPOTS';if(!map)return;for(const [area,type,lng,lat,title,description] of spots){if(area!==region||(category!=='all'&&type!==category))continue;const el=document.createElement('button');el.type='button';el.className='tt-spot';el.dataset.category=type;el.textContent={meets:'TT',checkpoints:'●',vendors:'V'}[type];el.setAttribute('aria-label',title+' — demo '+type);const content=document.createElement('div'),heading=document.createElement('strong'),detail=document.createElement('p'),note=document.createElement('p');heading.textContent=title;detail.textContent=description;note.textContent='Prelaunch example only. No confirmed event or partner at this location.';content.append(heading,detail,note);const popup=new maplibregl.Popup({offset:20,maxWidth:'240px'}).setDOMContent(content);markers.push(new maplibregl.Marker({element:el}).setLngLat([lng,lat]).setPopup(popup).addTo(map));}}
function init(){if(map)return;if(!window.maplibregl){notice('Map could not load. Refresh to try again.');return}try{const r=regions[region];map=new maplibregl.Map({container:world.querySelector('.tt-map-canvas'),style:'https://tiles.openfreemap.org/styles/dark',center:r.center,zoom:r.zoom,attributionControl:true,scrollZoom:false,dragRotate:false,pitchWithRotate:false});map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');map.on('load',()=>{loaded=true;clearTimeout(timeout);status.hidden=true;paint()});map.on('style.load',()=>{loaded=true;clearTimeout(timeout);status.hidden=true});map.on('error',()=>{if(!loaded)notice('Map unavailable right now. Please try again.',true)});watchLoad();paint();new ResizeObserver(()=>map.resize()).observe(world)}catch(e){map=undefined;notice('Interactive map requires a browser with WebGL enabled.')}}
function choose(value,expand=true){if(!['all','meets','checkpoints','vendors'].includes(value))return;category=value;if(expand)openPage('navigation');init();paint();fly()}
const originalOpen=openPage;openPage=function(name){originalOpen(name);if(name==='navigation'||name==='dashboard'){(name==='navigation'?full:dashboard).append(world);init();requestAnimationFrame(()=>map?.resize())}};
world.querySelector('.tt-map-expand').onclick=()=>openPage('navigation');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>choose(b.dataset.filter,false));document.querySelectorAll('[data-map-shortcut]').forEach(b=>b.onclick=()=>choose(b.dataset.mapShortcut));document.querySelector('#map-region').onchange=e=>{if(!regions[e.target.value])return;region=e.target.value;paint();fly()};
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='ttspot-map')choose(e.data.category)});
const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){init();observer.disconnect()}});observer.observe(dashboard);
})();
